text = text.replace("                        'question_type_enum': row.question_type_enum,\n                        'subject_code': row.subject_name\n                    })", "                        'question_type_enum': row.question_type_enum,\n                        'subject_code': row.subject_name,\n                        'instrument_id': getattr(row, 'instrument_id', None)\n                    })", 1)
text = text.replace("                        'question_type_enum': q_enum,\n                        # 鍏煎涓嶅悓閿悕锛歴ubject/subject_code/subjectCode/code/id\n                        'subject_code': (", "                        'question_type_enum': q_enum,\n                        'instrument_id': item.get('instrument_id'),\n                        # 鍏煎涓嶅悓閿悕锛歴ubject/subject_code/subjectCode/code/id\n                        'subject_code': (", 1)
text = text.replace("                        'question_type_enum': 'exam',\n                        'subject_code': item,\n                    })", "                        'question_type_enum': 'exam',\n                        'instrument_id': None,\n                        'subject_code': item,\n                    })", 1)
path.write_text(text, encoding='utf-8')
